--
-- Table structure for table `alerts`
--

DROP TABLE IF EXISTS `alerts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `alerts` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `alert_uuid` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'UUID duy nhất cho alert',
  `alert_type` enum('blacklist_detected','unauthorized_access','system_error','camera_offline','speed_violation','overstay','no_exit_record','suspicious_activity','multiple_entry','custom') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Loại cảnh báo',
  `severity` enum('low','medium','high','critical') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'medium' COMMENT 'Mức độ nghiêm trọng',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Tiêu đề cảnh báo',
  `message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Nội dung cảnh báo',
  `summary` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Tóm tắt ngắn gọn',
  `plate_number` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Biển số liên quan',
  `detection_id` bigint unsigned DEFAULT NULL COMMENT 'ID phát hiện liên quan',
  `camera_id` int unsigned DEFAULT NULL COMMENT 'Camera liên quan',
  `location_id` int unsigned DEFAULT NULL COMMENT 'Vị trí liên quan',
  `user_id` int unsigned DEFAULT NULL COMMENT 'Người dùng liên quan',
  `vehicle_id` int unsigned DEFAULT NULL COMMENT 'Phương tiện liên quan',
  `alert_data` json DEFAULT NULL COMMENT 'Dữ liệu chi tiết (JSON)',
  `context_data` json DEFAULT NULL COMMENT 'Dữ liệu ngữ cảnh (JSON)',
  `evidence_files` json DEFAULT NULL COMMENT 'Danh sách file bằng chứng (JSON array)',
  `status` enum('new','acknowledged','investigating','resolved','dismissed','false_positive') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'new' COMMENT 'Trạng thái xử lý',
  `priority_score` tinyint unsigned DEFAULT '50' COMMENT 'Điểm ưu tiên (0-100)',
  `acknowledged_by` int unsigned DEFAULT NULL COMMENT 'Người xác nhận',
  `acknowledged_at` datetime DEFAULT NULL COMMENT 'Thời gian xác nhận',
  `resolved_by` int unsigned DEFAULT NULL COMMENT 'Người giải quyết',
  `resolved_at` datetime DEFAULT NULL COMMENT 'Thời gian giải quyết',
  `resolution_notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Ghi chú giải quyết',
  `resolution_time_minutes` int unsigned DEFAULT NULL COMMENT 'Thời gian giải quyết (phút)',
  `auto_dismiss_at` datetime DEFAULT NULL COMMENT 'Tự động bỏ qua vào lúc',
  `escalation_level` tinyint unsigned DEFAULT '0' COMMENT 'Mức độ leo thang (0-5)',
  `escalated_at` datetime DEFAULT NULL COMMENT 'Thời gian leo thang',
  `notification_sent` tinyint(1) DEFAULT '0' COMMENT 'Đã gửi thông báo',
  `notification_channels` json DEFAULT NULL COMMENT 'Kênh thông báo đã gửi (JSON array)',
  `notification_attempts` tinyint unsigned DEFAULT '0' COMMENT 'Số lần thử gửi thông báo',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `alert_uuid` (`alert_uuid`),
  KEY `detection_id` (`detection_id`),
  KEY `user_id` (`user_id`),
  KEY `vehicle_id` (`vehicle_id`),
  KEY `acknowledged_by` (`acknowledged_by`),
  KEY `resolved_by` (`resolved_by`),
  KEY `idx_alert_type` (`alert_type`),
  KEY `idx_severity` (`severity`),
  KEY `idx_status` (`status`),
  KEY `idx_created_at` (`created_at`),
  KEY `idx_plate_number` (`plate_number`),
  KEY `idx_camera_id` (`camera_id`),
  KEY `idx_location_id` (`location_id`),
  KEY `idx_priority_score` (`priority_score` DESC),
  KEY `idx_severity_status_time` (`severity` DESC,`status`,`created_at` DESC),
  KEY `idx_escalation` (`escalation_level`,`created_at`),
  CONSTRAINT `alerts_ibfk_1` FOREIGN KEY (`detection_id`) REFERENCES `license_plate_detections` (`id`) ON DELETE CASCADE,
  CONSTRAINT `alerts_ibfk_3` FOREIGN KEY (`location_id`) REFERENCES `locations` (`id`) ON DELETE SET NULL,
  CONSTRAINT `alerts_ibfk_4` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `alerts_ibfk_5` FOREIGN KEY (`vehicle_id`) REFERENCES `vehicles` (`id`) ON DELETE SET NULL,
  CONSTRAINT `alerts_ibfk_6` FOREIGN KEY (`acknowledged_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `alerts_ibfk_7` FOREIGN KEY (`resolved_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Bảng cảnh báo hệ thống';
/*!40101 SET character_set_client = @saved_cs_client */;

