--
-- Table structure for table `license_plate_detections`
--

DROP TABLE IF EXISTS `license_plate_detections`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `license_plate_detections` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `detection_uuid` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'UUID duy nhất cho detection',
  `plate_number` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Biển số phát hiện',
  `raw_plate_text` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Text thô từ OCR',
  `camera_id` int DEFAULT NULL,
  `location_id` int DEFAULT NULL,
  `vehicle_id` int unsigned DEFAULT NULL COMMENT 'ID phương tiện (nếu đã xác định)',
  `detected_at` datetime NOT NULL COMMENT 'Thời gian phát hiện',
  `direction` enum('inbound','outbound','unknown') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'unknown' COMMENT 'Hướng di chuyển',
  `confidence_score` decimal(5,4) NOT NULL COMMENT 'Độ tin cậy tổng thể (0-1)',
  `ocr_confidence` decimal(5,4) DEFAULT NULL COMMENT 'Độ tin cậy OCR (0-1)',
  `detection_confidence` decimal(5,4) DEFAULT NULL COMMENT 'Độ tin cậy phát hiện vật thể (0-1)',
  `original_image_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Đường dẫn ảnh gốc',
  `cropped_plate_image_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Đường dẫn ảnh biển số đã cắt',
  `annotated_image_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Đường dẫn ảnh đã chú thích',
  `detected_vehicle_type` enum('motorcycle','car','truck','bus','other') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Loại xe phát hiện',
  `detected_vehicle_color` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Màu xe phát hiện',
  `vehicle_speed` decimal(6,2) DEFAULT NULL COMMENT 'Tốc độ (km/h)',
  `bbox_x1` smallint unsigned DEFAULT NULL COMMENT 'Tọa độ X1 của bounding box',
  `bbox_y1` smallint unsigned DEFAULT NULL COMMENT 'Tọa độ Y1 của bounding box',
  `bbox_x2` smallint unsigned DEFAULT NULL COMMENT 'Tọa độ X2 của bounding box',
  `bbox_y2` smallint unsigned DEFAULT NULL COMMENT 'Tọa độ Y2 của bounding box',
  `is_verified` tinyint(1) DEFAULT '0' COMMENT 'Đã xác minh thủ công',
  `verified_by` int unsigned DEFAULT NULL COMMENT 'Người xác minh',
  `verified_at` datetime DEFAULT NULL COMMENT 'Thời gian xác minh',
  `verification_notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Ghi chú xác minh',
  `is_whitelist_match` tinyint(1) DEFAULT '0' COMMENT 'Khớp danh sách trắng',
  `is_blacklist_match` tinyint(1) DEFAULT '0' COMMENT 'Khớp danh sách đen',
  `alert_triggered` tinyint(1) DEFAULT '0' COMMENT 'Đã kích hoạt cảnh báo',
  `processing_time_ms` int unsigned DEFAULT NULL COMMENT 'Thời gian xử lý (ms)',
  `ai_model_version` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Phiên bản model AI',
  `raw_detection_data` json DEFAULT NULL COMMENT 'Dữ liệu thô từ AI (JSON)',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `source_type` enum('camera','video_upload') COLLATE utf8mb4_unicode_ci DEFAULT 'camera' COMMENT 'Nguồn dữ liệu: camera live hoặc video upload',
  `video_filename` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Tên file video (nếu từ upload)',
  `camera_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Tên camera (cho camera live)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `detection_uuid` (`detection_uuid`),
  KEY `vehicle_id` (`vehicle_id`),
  KEY `verified_by` (`verified_by`),
  KEY `idx_plate_number` (`plate_number`),
  KEY `idx_camera_id` (`camera_id`),
  KEY `idx_location_id` (`location_id`),
  KEY `idx_detected_at` (`detected_at`),
  KEY `idx_confidence_score` (`confidence_score`),
  KEY `idx_direction` (`direction`),
  KEY `idx_verified` (`is_verified`),
  KEY `idx_plate_time` (`plate_number`,`detected_at` DESC),
  KEY `idx_location_time` (`location_id`,`detected_at` DESC),
  KEY `idx_camera_time` (`camera_id`,`detected_at` DESC),
  KEY `idx_whitelist_match` (`is_whitelist_match`),
  KEY `idx_blacklist_match` (`is_blacklist_match`),
  KEY `idx_alert_triggered` (`alert_triggered`),
  CONSTRAINT `license_plate_detections_ibfk_3` FOREIGN KEY (`vehicle_id`) REFERENCES `vehicles` (`id`) ON DELETE SET NULL,
  CONSTRAINT `license_plate_detections_ibfk_4` FOREIGN KEY (`verified_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=6475 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Bảng phát hiện biển số xe';
/*!40101 SET character_set_client = @saved_cs_client */;

