--
-- Table structure for table `locations`
--

DROP TABLE IF EXISTS `locations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `locations` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Tên vị trí',
  `code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Mã vị trí',
  `address` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Địa chỉ',
  `latitude` decimal(10,8) DEFAULT NULL COMMENT 'Vĩ độ',
  `longitude` decimal(11,8) DEFAULT NULL COMMENT 'Kinh độ',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Mô tả',
  `zone_type` enum('entrance','exit','checkpoint','parking','restricted','monitoring_zone') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'checkpoint' COMMENT 'Loại khu vực',
  `is_restricted` tinyint(1) DEFAULT '0' COMMENT 'Khu vực hạn chế',
  `Ox` int DEFAULT NULL,
  `Oy` int DEFAULT NULL,
  `is_main_entry` tinyint(1) DEFAULT '0' COMMENT 'Là lối vào chính',
  `is_main_exit` tinyint(1) DEFAULT '0' COMMENT 'Là lối ra chính',
  `max_stay_duration_hours` smallint unsigned DEFAULT '24' COMMENT 'Thời gian lưu trú tối đa (giờ)',
  `is_alert_on_overstay` tinyint(1) DEFAULT '1' COMMENT 'Cảnh báo khi ở lại quá lâu',
  `is_alert_on_no_exit` tinyint(1) DEFAULT '1' COMMENT 'Cảnh báo khi không có bản ghi ra',
  `is_active` tinyint(1) DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`),
  KEY `parent_location_id` (`Ox`),
  KEY `idx_name` (`name`),
  KEY `idx_code` (`code`),
  KEY `idx_zone_type` (`zone_type`),
  KEY `idx_active` (`is_active`),
  KEY `idx_entry_exit_pair` (`Oy`)
) ENGINE=InnoDB AUTO_INCREMENT=68 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Bảng vị trí/khu vực giám sát';
/*!40101 SET character_set_client = @saved_cs_client */;

