--
-- Table structure for table `notification_settings`
--

DROP TABLE IF EXISTS `notification_settings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `notification_settings` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned NOT NULL COMMENT 'Người dùng',
  `alert_type` enum('blacklist_detected','unauthorized_access','system_error','camera_offline','speed_violation','overstay','no_exit_record','suspicious_activity','multiple_entry','custom','all') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Loại cảnh báo',
  `email_enabled` tinyint(1) DEFAULT '1' COMMENT 'Bật thông báo email',
  `sms_enabled` tinyint(1) DEFAULT '0' COMMENT 'Bật thông báo SMS',
  `push_enabled` tinyint(1) DEFAULT '1' COMMENT 'Bật thông báo đẩy',
  `webhook_enabled` tinyint(1) DEFAULT '0' COMMENT 'Bật webhook',
  `min_severity` enum('low','medium','high','critical') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'medium' COMMENT 'Mức độ tối thiểu để thông báo',
  `webhook_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'URL webhook',
  `webhook_secret` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Secret key cho webhook',
  `location_filter` json DEFAULT NULL COMMENT 'Lọc theo vị trí (JSON array of location_ids)',
  `time_filter` json DEFAULT NULL COMMENT 'Lọc theo thời gian (JSON với start_time, end_time)',
  `max_alerts_per_hour` tinyint unsigned DEFAULT '10' COMMENT 'Số cảnh báo tối đa mỗi giờ',
  `cooldown_minutes` tinyint unsigned DEFAULT '5' COMMENT 'Thời gian chờ giữa các thông báo (phút)',
  `is_active` tinyint(1) DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_alert_type` (`user_id`,`alert_type`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_alert_type` (`alert_type`),
  KEY `idx_active` (`is_active`),
  CONSTRAINT `notification_settings_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Bảng cài đặt thông báo';
/*!40101 SET character_set_client = @saved_cs_client */;

