--
-- Table structure for table `watermarks`
--

DROP TABLE IF EXISTS `watermarks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `watermarks` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Tên watermark',
  `watermark_type` enum('text','image','combined') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'text' COMMENT 'Loại watermark',
  `image_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Đường dẫn ảnh watermark',
  `image_format` enum('PNG','JPG','SVG') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Định dạng ảnh',
  `text_content` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Nội dung text watermark',
  `font_family` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'Arial' COMMENT 'Font chữ',
  `font_size` tinyint unsigned DEFAULT '12' COMMENT 'Kích thước font',
  `font_weight` enum('normal','bold','lighter') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'normal' COMMENT 'Độ đậm font',
  `text_color` varchar(7) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '#FFFFFF' COMMENT 'Màu chữ (hex)',
  `position` enum('top-left','top-center','top-right','middle-left','middle-center','middle-right','bottom-left','bottom-center','bottom-right','custom') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'bottom-right' COMMENT 'Vị trí watermark',
  `custom_x_percent` decimal(5,2) DEFAULT NULL COMMENT 'Vị trí X tùy chỉnh (phần trăm)',
  `custom_y_percent` decimal(5,2) DEFAULT NULL COMMENT 'Vị trí Y tùy chỉnh (phần trăm)',
  `size_percent` tinyint unsigned DEFAULT '10' COMMENT 'Kích thước theo phần trăm',
  `opacity` decimal(3,2) DEFAULT '0.50' COMMENT 'Độ trong suốt (0-1)',
  `rotation_degrees` smallint DEFAULT '0' COMMENT 'Góc xoay (độ)',
  `background_color` varchar(7) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Màu nền (hex)',
  `border_width` tinyint unsigned DEFAULT '0' COMMENT 'Độ dày viền',
  `border_color` varchar(7) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Màu viền (hex)',
  `is_enabled` tinyint(1) DEFAULT '1' COMMENT 'Có áp dụng watermark',
  `apply_to` enum('all','detections','exports','reports','alerts') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'all' COMMENT 'Áp dụng cho',
  `quality_threshold` decimal(3,2) DEFAULT '0.00' COMMENT 'Ngưỡng chất lượng để áp dụng (0-1)',
  `preview_image_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Đường dẫn ảnh preview',
  `usage_count` int unsigned DEFAULT '0' COMMENT 'Số lần sử dụng',
  `created_by` int unsigned DEFAULT NULL COMMENT 'Người tạo',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`),
  KEY `created_by` (`created_by`),
  KEY `idx_name` (`name`),
  KEY `idx_enabled` (`is_enabled`),
  KEY `idx_type` (`watermark_type`),
  KEY `idx_apply_to` (`apply_to`),
  CONSTRAINT `watermarks_ibfk_1` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Bảng quản lý watermark';
/*!40101 SET character_set_client = @saved_cs_client */;

